function editOrder(id,cid){let o=db.orders.find(x=>x.id===id)||{clientId:cid||'',date:today(),status:'Pendiente',kg:'',price:client(cid)?.defaultPrice||'',paid:0,notes:''};openModal(`<div class="row"><h2>${id?'Editar pedido':'Nuevo pedido'}</h2><button class="close" onclick="closeModal()">×</button></div><div class="spacer"></div><form id="form"><label>Cliente<select name="clientId" id="order-client" required><option value="">Selecciona un cliente</option>${db.clients.map(c=>`<option value="${esc(c.id)}" ${o.clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="grid"><label>Cantidad en kilos<input name="kg" type="number" min="0.01" step="0.01" required value="${esc(o.kg)}"></label><label>Precio por kilo ($)<input name="price" type="number" min="1" step="1" required value="${esc(o.price)}"></label></div><label>Fecha prevista<input name="date" type="date" value="${esc(o.date)}"></label><label>Notas<textarea name="notes">${esc(o.notes)}</textarea></label>${id?`<p class="muted">Estado: ${esc(o.status)} · Pagado: ${money(o.paid)}. Los pagos se registran por separado.</p>`:''}<div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Guardar pedido</button></div></form>`);$('#order-client').onchange=e=>{if(!id)$('#form [name=price]').value=client(e.target.value)?.defaultPrice||''};$('#form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(id&&d.clientId!==o.clientId&&(Number(o.paid)||delivered(o))){alert('No puedes cambiar el cliente de una entrega o pedido con pagos.');return}if(id&&Number(o.paid)>Math.round(Number(d.kg)*Number(d.price))){alert('El total no puede ser menor que lo ya pagado.');return}if(id){Object.assign(o,d);delete o.totalOverride}else db.orders.push({id:uid(),...d,status:'Pendiente',paid:0});save();closeModal();render()}}
function allocate(id,amount,date){let left=Number(amount),orders=db.orders.filter(o=>o.clientId===id&&delivered(o)&&balance(o)>0).sort((a,b)=>(a.deliveredDate||a.date||'').localeCompare(b.deliveredDate||b.date||''));for(let o of orders){let n=Math.min(left,balance(o));if(n>0){o.paid=(Number(o.paid)||0)+n;db.payments.push({id:uid(),clientId:id,orderId:o.id,amount:n,date});left-=n}if(left<=0)break}}
function deliver(id){let o=db.orders.find(x=>x.id===id),previous=owed(o.clientId),available=previous+balance(o),prev=fifoPreview(o.kg),partes=prev.parts.map(x=>'Tanda del '+short(x.b.date)+' ('+kg(x.kg)+')').join(', ')||'ninguna tanda con kilos';openModal(`<div class="row"><h2>Entregar y cobrar</h2><button class="close" onclick="closeModal()">×</button></div><p class="muted">${esc(client(o.clientId)?.name||'Cliente')}</p><div class="tip">Deuda anterior: <b>${money(previous)}</b><br>Entrega de hoy: <b>${money(total(o))}</b><br>Total antes del pago: <b>${money(available)}</b><br><span class="muted">Se descuenta de: ${partes}</span>${prev.missing>0.001?`<br><span class="neg">Faltan ${kg(prev.missing)} según tus registros</span>`:''}</div><div class="spacer"></div><form id="form"><label>Fecha de entrega<input name="date" type="date" required value="${today()}"></label><label>Pago recibido ahora ($)<input name="amount" type="number" min="0" max="${available}" step="1" value="0" required></label><p class="muted">El pago se aplica primero a las entregas más antiguas. Puedes dejarlo en cero si pagará después.</p><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Confirmar entrega</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),s=stock();if(s!==null&&Number(o.kg)>s&&!confirm('Según tus registros solo te quedan '+kg(s)+' y esta entrega es de '+kg(o.kg)+'. ¿Entregar igual?'))return;o.status='Entregado';o.deliveredAt=new Date().toISOString();o.deliveredDate=d.date;allocate(o.clientId,d.amount,d.date);save();closeModal();render()}}
function payment(id){let c=client(id),b=owed(id);openModal(`<div class="row"><h2>Registrar pago</h2><button class="close" onclick="closeModal()">×</button></div><p class="muted">${esc(c?.name||'Cliente')} · Saldo: ${money(b)}</p><form id="form"><label>Fecha del pago<input name="date" type="date" required value="${today()}"></label><label>Abono recibido ($)<input name="amount" type="number" min="1" max="${b}" step="1" required></label><p class="muted">Se aplica primero a las entregas más antiguas.</p><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Guardar pago</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));allocate(id,d.amount,d.date);save();closeModal();render()}}
function history(id){let os=db.orders.filter(o=>o.clientId===id&&delivered(o)).sort((a,b)=>(b.deliveredDate||b.date||'').localeCompare(a.deliveredDate||a.date||'')), ps=db.payments.filter(p=>p.clientId===id);openModal(`<div class="row"><h2>Movimientos</h2><button class="close" onclick="closeModal()">×</button></div><p>${esc(client(id)?.name||'Cliente')} · Saldo ${money(owed(id))}</p>${os.map(o=>`<div class="item"><b>Entrega ${fmt(o.deliveredDate||o.date)} · ${money(total(o))}</b><p>Pagado ${money(o.paid)} · Saldo ${money(balance(o))}</p>${ps.filter(p=>p.orderId===o.id).map(p=>`<p>Abono ${fmt(p.date)}: ${money(p.amount)}</p>`).join('')}${(Number(o.paid)||0)>ps.filter(p=>p.orderId===o.id).reduce((s,p)=>s+Number(p.amount),0)?'<p>Incluye pagos anteriores sin fecha detallada.</p>':''}</div>`).join('')||'<p>Sin entregas.</p>'}`)}
function whatsapp(id){let c=client(id),phone=String(c.phone||'').replace(/\D/g,'');if(phone.length===9)phone='56'+phone;if(!/^569\d{8}$/.test(phone)){alert('Revisa el número: usa +56 9 seguido de 8 dígitos.');return}
let ult=waUltima(c.id),dias=diasSinComprar(c),precio=Number(c.defaultPrice)||Number(ult?.price)||'',dia=db.settings.waDia||'',estilo=db.settings.waEstilo||(ult?'mismo':'cercano');if(estilo==='mismo'&&!ult)estilo='cercano';
let info=ult?`${dias!==null?'Lleva <b>'+dias+' día'+(dias===1?'':'s')+'</b> sin comprar · ':''}la última vez: ${kg(ult.kg)} a ${money(ult.price)} el kilo`:'Todavía no tiene compras registradas';
let chips=WA_ESTILOS.filter(e=>e.id!=='mismo'||ult).map(e=>`<button type="button" class="secondary wa-chip" data-estilo="${e.id}">${e.nombre}</button>`).join('');
openModal(`<div class="row"><h2>Mensaje para ${esc(c.name)}</h2><button class="close" onclick="closeModal()">×</button></div><p class="muted">${info}</p><form id="form"><label>Elige un mensaje</label><div class="actions wa-chips">${chips}</div><div class="grid dos"><label>Precio por kilo ($)<input id="wa-precio" type="number" min="0" step="1" inputmode="numeric" value="${esc(precio)}" placeholder="Opcional"></label><label>Día de reparto<input id="wa-dia" value="${esc(dia)}" placeholder="Ej.: el jueves"></label></div><label>Mensaje (puedes cambiarlo)<textarea name="message" id="wa-msg" required rows="5"></textarea></label><label>Enviar por<select id="wa-app">${opcionesWaApp(db.settings.waApp)}</select></label><p class="muted">Al abrir WhatsApp, el cliente queda marcado como contactado hoy y deja de salir en «Clientes para llamar» durante una semana.</p><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Abrir WhatsApp ↗</button></div></form>`);
let escribir=()=>{$('#wa-msg').value=waTexto(estilo,c,ult,Number($('#wa-precio').value)||0,$('#wa-dia').value.trim());document.querySelectorAll('.wa-chip').forEach(b=>{let x=b.dataset.estilo===estilo;b.classList.toggle('primary',x);b.classList.toggle('secondary',!x)})};
document.querySelectorAll('.wa-chip').forEach(b=>b.onclick=()=>{estilo=b.dataset.estilo;escribir()});['#wa-precio','#wa-dia'].forEach(s=>$(s).oninput=escribir);escribir();
$('#form').onsubmit=e=>{e.preventDefault();let msg=$('#wa-msg').value;let app=$('#wa-app').value,listo=()=>{db.settings.waApp=app;db.settings.waEstilo=estilo;db.settings.waDia=$('#wa-dia')?.value.trim()||db.settings.waDia||'';c.lastContact=today();save();closeModal();render();aviso(c.name+' quedó marcado como contactado hoy')};if(app==='compartir'&&navigator.share){db.settings.waDia=$('#wa-dia').value.trim();navigator.share({text:msg}).then(listo).catch(err=>{if(err&&err.name==='AbortError')return;abrirWhatsApp(phone,msg,'');listo()});return}abrirWhatsApp(phone,msg,app==='compartir'?'':app);listo()}}
const WA_ESTILOS=[{id:'mismo',nombre:'Lo mismo de siempre'},{id:'cercano',nombre:'Cercano'},{id:'precio',nombre:'Con precio'},{id:'sector',nombre:'Paso por tu sector'}];
function waUltima(id){return db.orders.filter(o=>o.clientId===id&&delivered(o)).sort((a,b)=>(b.deliveredDate||b.date||'').localeCompare(a.deliveredDate||a.date||''))[0]||null}
function waTexto(estilo,c,ult,precio,dia){let h=new Date().getHours(),saludo=h<12?'Buenos días':h<20?'Buenas tardes':'Buenas noches',n=String(c.name||'').trim(),p=precio?money(precio)+' el kilo':'',cuando=dia?dia:'esta semana',Dia=s=>s.charAt(0).toUpperCase()+s.slice(1),sec=String(c.sector||'').trim();
if(estilo==='mismo'&&ult)return `${saludo}, ${n}, ¿cómo va todo? 😊 La última vez te llevé ${kg(ult.kg)} de palta Hass. ¿Te reservo lo mismo para ${cuando}?${p?' Está a '+p+'.':''} 🥑`;
if(estilo==='precio')return `¡Hola ${n}! 🥑 ${p?Dia(cuando)+' tengo palta Hass a '+p+'.':'Tengo palta Hass muy buena para '+cuando+'.'} ¿Cuántos kilos te llevo?`;
if(estilo==='sector')return `${saludo}, ${n} 👋 ${Dia(cuando)} ando repartiendo paltas ${sec?'en '+sec:'por tu sector'}. ¿Te dejo unos kilos de palta Hass?${p?' Está a '+p+'.':''} 🥑`;
return `¡Hola ${n}! 👋 ¿Cómo estás? ${ult?'Hace tiempo que no te llevo paltas.':'Te escribo para ofrecerte paltas.'} Tengo palta Hass muy rica para ${cuando} 🥑${p?', a '+p:''}. ¿Te guardo unos kilos?`}
function setStock(){let s=stock(),reg=s===null?0:s;openModal(`<div class="row"><h2>Conteo de stock</h2><button class="close" onclick="closeModal()">×</button></div><p class="muted">Según tus registros tienes <b>${kg(reg)}</b>. Cuenta los kilos disponibles ahora.</p><div class="tip">Si cuentas más kilos, se crea una compra de ajuste por la diferencia; si cuentas menos, se crea una merma.</div><form id="form"><label>Kilos que tienes ahora<input name="kg" type="number" min="0" step="0.01" required></label><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Guardar conteo</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let n=Number(new FormData(e.target).get('kg')),dif=r3(n-reg),now=new Date().toISOString();if(!dif){closeModal();return}if(dif<0)db.losses.push({id:uid(),kg:-dif,cause:'Ajuste de conteo',date:today(),createdAt:now,notes:''});else db.purchases.push({id:uid(),date:today(),name:'Ajuste de conteo',kg:dif,price:0,extra:0,notes:'',createdAt:now});save();closeModal();render()}}
function purchase(id){let p=id?db.purchases.find(x=>x.id===id):null;openModal(`<div class="row"><h2>${p?'Editar compra':'Nueva compra'}</h2><button class="close" onclick="closeModal()">×</button></div><div class="spacer"></div><form id="form"><label>Fecha<input name="date" type="date" required value="${esc(p?.date||today())}"></label><label>Proveedor<input name="name" required value="${esc(p?.name||'')}"></label><div class="grid"><label>Kilos<input name="kg" type="number" min="0.01" step="0.01" required value="${esc(p?.kg??'')}"></label><label>Precio por kilo ($)<input name="price" type="number" min="0" step="1" required value="${esc(p?.price??'')}"></label></div><label>Otros costos del viaje ($)<input name="extra" type="number" min="0" step="1" value="${esc(p?.extra??0)}"></label><label>Notas<textarea name="notes">${esc(p?.notes||'')}</textarea></label><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Guardar compra</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(p)Object.assign(p,d);else db.purchases.push({id:uid(),...d,createdAt:new Date().toISOString()});save();closeModal();render()}}
function editPurchase(id){purchase(id)}
function loss(){let lg=ledger(),opts=lg.batches.filter(b=>b.left>0).sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(b=>`<option value="${esc(b.id)}">Tanda del ${short(b.date)}${b.name?' · '+esc(b.name):''} · quedan ${kg(b.left)}</option>`).join('');openModal(`<div class="row"><h2>Registrar merma</h2><button class="close" onclick="closeModal()">×</button></div><div class="spacer"></div><form id="form"><label>Fecha<input name="date" type="date" required value="${today()}"></label><label>Kilos perdidos<input name="kg" type="number" min="0.01" step="0.01" required></label><label>Causa<select name="cause"><option>Maduración</option><option>Daño</option><option>Pudrición</option><option>Otra</option></select></label><label>¿De qué tanda?<select name="batchId"><option value="">La más antigua (automático)</option>${opts}</select></label><label>Notas<textarea name="notes"></textarea></label><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Guardar merma</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(!d.batchId)delete d.batchId;db.losses.push({id:uid(),...d,createdAt:new Date().toISOString()});save();closeModal();render()}}
function exportData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:VERSION,exported:today(),...db},null,2)],{type:'application/json'}));a.download='kpal-respaldo-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importData(input){let f=input.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!Array.isArray(x.clients)&&ppClientes(x)){showPPImport(ppClientes(x));return}if(!Array.isArray(x.clients)||!Array.isArray(x.orders))throw Error();if(confirm('Esto reemplazará los datos actuales. Descarga primero un respaldo. ¿Continuar?')){db=normalize(x);migrateV22();save();render();alert('Respaldo restaurado.')}}catch{alert('El archivo no es un respaldo válido de Kpal.')}finally{input.value=''}};r.readAsText(f)}migrateV22();render();
function cancelOrder(id){let o=db.orders.find(x=>x.id===id);if(!o||delivered(o))return;if(Number(o.paid)>0){alert('Este pedido tiene pagos registrados y no se puede cancelar.');return}if(!confirm('¿Cancelar el pedido de '+(client(o.clientId)?.name||'este cliente')+' ('+o.kg+' kg)? Se borrará de la lista.'))return;db.orders=db.orders.filter(x=>x.id!==id);save();render()}
function undoDeliver(id){let o=db.orders.find(x=>x.id===id);if(!o||!delivered(o))return;let sum=Number(o.paid)||0;if(!confirm('¿Deshacer esta entrega? El pedido vuelve a "Pendiente".'+(sum?' Se quitarán los pagos aplicados a esta entrega ('+money(sum)+'). Si el cliente sí pagó, vuelve a registrar el pago después.':'')))return;db.payments=db.payments.filter(p=>p.orderId!==id);o.status='Pendiente';o.paid=0;delete o.deliveredAt;delete o.deliveredDate;save();render()}
function deleteClient(id){let c=client(id);if(!c)return;let os=db.orders.filter(o=>o.clientId===id);if(os.some(o=>!delivered(o))){alert('Este cliente tiene pedidos pendientes. Cancélalos o entrégalos antes de eliminarlo.');return}if(owed(id)>0){alert('Este cliente todavía debe '+money(owed(id))+'. Registra el pago antes de eliminarlo.');return}if(!confirm('¿Eliminar a '+c.name+'? Sus entregas pasadas se conservan.'))return;os.forEach(o=>o.clientName=c.name);db.clients=db.clients.filter(x=>x.id!==id);save();closeModal();render()}
function deleteMove(type,id){let list=type==='Compra'?'purchases':'losses',x=db[list].find(m=>m.id===id);if(!x)return;let extra='';if(type==='Compra'){let b=ledger().batches.find(b=>b.id===id);if(b&&(b.soldKg>0.001||b.lossKg>0.001))extra=' Los kilos vendidos o perdidos de esta tanda se pasarán a otras tandas.'}if(!confirm('¿Eliminar esta '+type.toLowerCase()+' de '+kg(x.kg)+' del '+fmt(x.date)+'?'+extra))return;db[list]=db[list].filter(m=>m.id!==id);save();render()}

function short(d){return d?fmt(d).slice(0,5):'sin fecha'}
function jsq(s){return "'"+String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/&/g,'\\x26').replace(/</g,'\\x3c').replace(/>/g,'\\x3e').replace(/"/g,'\\x22').replace(/[\r\n]/g,' ')+"'"}
function telLink(p){let d=String(p||'').replace(/\D/g,'');if(d&&!d.startsWith('56'))d='56'+d;return 'tel:+'+d}
function mapLink(c){c=c||{};if(tieneUbicacion(c))return 'https://www.google.com/maps/search/?api=1&query='+Number(c.lat)+','+Number(c.lng);return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent([c.address,c.sector||'Sin sector','Chile'].filter(Boolean).join(', '))}
function sectorOrder(){let out=[],add=s=>{s=String(s??'').trim()||'Sin sector';if(s!=='Sin sector'&&!out.includes(s))out.push(s)};(db.settings.routeOrder||[]).forEach(add);SECTORES.forEach(add);[...new Set(db.clients.map(c=>String(c.sector??'').trim()).filter(Boolean))].filter(s=>s!=='Sin sector'&&!out.includes(s)).sort((a,b)=>a.localeCompare(b,'es')).forEach(s=>out.push(s));out.push('Sin sector');return out}
function moveSector(nombre,dir){if(!nombre||nombre==='Sin sector')return;let list=sectorOrder().filter(s=>s!=='Sin sector'),i=list.indexOf(nombre),j=i+dir;if(i<0||j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];db.settings.routeOrder=list;save();render()}
function diasDesde(fecha,hasta=today()){if(!fecha||typeof fecha!=='string')return null;let a=fecha.split('-').map(Number),b=hasta.split('-').map(Number);if(a.length!==3||b.length!==3||a.some(Number.isNaN)||b.some(Number.isNaN))return null;return Math.round((new Date(b[0],b[1]-1,b[2],12)-new Date(a[0],a[1]-1,a[2],12))/86400000)}
function diasSinComprar(c){return diasDesde(lastPurchase(c.id))}
function tieneUbicacion(c){return !!(c&&c.lat!=null&&c.lng!=null&&c.lat!==''&&c.lng!=='')}
function mapPunto(lat,lng){return 'https://www.google.com/maps/search/?api=1&query='+Number(lat)+','+Number(lng)}
function haversine(a,b,c,d){let r=Math.PI/180,R=6371,dLat=(c-a)*r,dLng=(d-b)*r,x=Math.sin(dLat/2)**2+Math.cos(a*r)*Math.cos(c*r)*Math.sin(dLng/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(x)))}
function fechaMas(fecha,dias){let a=String(fecha||'').split('-').map(Number);if(a.length!==3||a.some(Number.isNaN))return fecha;return isoDate(new Date(a[0],a[1]-1,a[2]+(Number(dias)||0)))}
function frecuencia(id){let fechas=[...new Set(db.orders.filter(o=>o.clientId===id&&delivered(o)).map(o=>o.deliveredDate||o.date).filter(Boolean))].sort();if(fechas.length<3)return null;let ints=[];for(let i=1;i<fechas.length;i++){let d=diasDesde(fechas[i-1],fechas[i]);if(d!==null&&d>0)ints.push(d)}if(!ints.length)return null;let u=ints.slice(-6).sort((a,b)=>a-b),n=u.length,m=n%2?u[(n-1)/2]:(u[n/2-1]+u[n/2])/2,cada=Math.max(1,Math.round(m)),ultima=fechas[fechas.length-1];return {cada,ultima,proxima:fechaMas(ultima,cada),compras:fechas.length}}
function kgSugerido(id){let ks=db.orders.filter(o=>o.clientId===id&&delivered(o)).sort((a,b)=>(b.deliveredDate||b.date||'').localeCompare(a.deliveredDate||a.date||'')).slice(0,5).map(o=>Number(o.kg)||0).sort((a,b)=>a-b);if(!ks.length)return 0;let n=ks.length,m=n%2?ks[(n-1)/2]:(ks[n/2-1]+ks[n/2])/2;return Math.round(m*2)/2}
function sugeridosParaRuta(fecha){let lim=Number(db.settings.inactiveDays)||14,toca=[],mucho=[];db.clients.forEach(c=>{if(db.orders.some(o=>o.clientId===c.id&&!delivered(o)))return;if(c.skipUntil&&c.skipUntil>=fecha)return;let f=frecuencia(c.id),dias=diasSinComprar(c),k=kgSugerido(c.id);if(f&&f.proxima&&f.proxima<=fecha)toca.push({c,f,kg:k,atraso:Math.max(0,diasDesde(f.proxima,fecha)||0)});else if(!f&&dias!==null&&dias>=lim)mucho.push({c,dias,kg:k})});toca.sort((a,b)=>b.atraso-a.atraso);mucho.sort((a,b)=>b.dias-a.dias);return [...toca,...mucho]}
function obtenerUbicacion(silencioso){return new Promise(resolve=>{let geo=typeof navigator!=='undefined'?navigator.geolocation:null;if(!geo){alert('Este navegador no permite obtener la ubicación. Prueba con Chrome o Safari actualizado.');resolve(null);return}let abierto=false;if(!silencioso){openModal(`<div class="ubi-espera"><h2>Buscando tu ubicación…</h2><p class="muted">Mantén el teléfono desbloqueado y con el GPS activo. Puede tardar unos segundos.</p></div>`);abierto=true}let cerrar=()=>{if(abierto){try{closeModal()}catch(e){}abierto=false}};geo.getCurrentPosition(p=>{cerrar();resolve({lat:p.coords.latitude,lng:p.coords.longitude,acc:p.coords.accuracy})},e=>{cerrar();alert(e&&e.code===1?'Para guardar la ubicación hay que permitirla en el navegador. Toca el candado junto a la dirección del sitio, activa «Ubicación» y vuelve a intentarlo.':'No se pudo obtener la ubicación. Prueba al aire libre, espera un momento y vuelve a intentarlo.');resolve(null)},{enableHighAccuracy:true,timeout:15000,maximumAge:0})})}
let ubicacionTmp=null;
async function guardarUbicacionAqui(){cerrarMenu();let u=await obtenerUbicacion();if(!u)return;ubicacionTmp=u;abrirUbicacionClientes()}
function abrirUbicacionClientes(){let u=ubicacionTmp;if(!u)return;openModal(`<div class="row"><h2>¿De qué cliente es esta ubicación?</h2><button class="close" onclick="closeModal()">×</button></div><p class="muted">Precisión: unos ${Math.round(u.acc||0)} m</p><input id="ub-buscar" placeholder="Buscar por nombre o sector" oninput="filtrarUbicacion()"><div class="spacer"></div><div class="list ubi-lista" id="ub-lista">${listaUbicacion('')}</div><div class="spacer"></div><button class="primary ubi-nuevo" onclick="nuevoClienteAqui()">+ Cliente nuevo aquí</button>`)}
function listaUbicacion(q){let u=ubicacionTmp;if(!u)return '';let q2=String(q||'').toLocaleLowerCase('es'),porNombre=(a,b)=>String(a.name||'').localeCompare(String(b.name||''),'es'),cerca=[],sin=[],resto=[];db.clients.filter(c=>!q2||[c.name,c.sector].some(v=>String(v||'').toLocaleLowerCase('es').includes(q2))).forEach(c=>{if(tieneUbicacion(c)){let d=haversine(u.lat,u.lng,Number(c.lat),Number(c.lng));if(d*1000<300)cerca.push({c,d});else resto.push(c)}else sin.push(c)});cerca.sort((a,b)=>a.d-b.d);sin.sort(porNombre);resto.sort(porNombre);let fila=(c,extra)=>`<article class="item row"><div><h3>${esc(c.name)}</h3><p>${esc(c.sector||'Sin sector')}${extra?' · '+extra:''}</p></div><button class="primary" onclick="asignarUbicacion('${c.id}')">Este</button></article>`;return [...cerca.map(x=>fila(x.c,'a '+Math.round(x.d*1000)+' m')),...sin.map(c=>fila(c,'sin ubicación')),...resto.map(c=>fila(c))].join('')||empty('Sin clientes','Prueba con otro nombre o crea uno nuevo.')}
function filtrarUbicacion(){let l=$('#ub-lista');if(l)l.innerHTML=listaUbicacion($('#ub-buscar').value)}
function asignarUbicacion(id){let c=client(id),u=ubicacionTmp;if(!c||!u)return;if(tieneUbicacion(c)&&!confirm('¿Cambiar la ubicación guardada de '+c.name+'?'))return;c.lat=u.lat;c.lng=u.lng;c.locAt=new Date().toISOString();save();closeModal();render();aviso('Ubicación guardada para '+c.name)}
function nuevoClienteAqui(){let u=ubicacionTmp;closeModal();editClient(null,u?{lat:u.lat,lng:u.lng,locAt:new Date().toISOString()}:null)}
function estadoUbicacion(lat,lng,locAt){if(lat===''||lng===''||lat==null||lng==null)return '<p class="muted">Sin ubicación guardada.</p>';return `<div class="tip">📍 Ubicación guardada${locAt?' el '+fmt(String(locAt).slice(0,10)):''} · <a href="${mapPunto(lat,lng)}" target="_blank" rel="noopener">Ver en el mapa</a></div>`}
async function usarUbicacionForm(){let f=$('#form');if(!f)return;let b=f.querySelector('button[onclick="usarUbicacionForm()"]'),txt=b?b.textContent:'';if(b){b.disabled=true;b.textContent='Buscando…'}let u=await obtenerUbicacion(true);if(b){b.disabled=false;b.textContent=txt}if(!u||!f.isConnected)return;f.elements.lat.value=u.lat;f.elements.lng.value=u.lng;f.elements.locAt.value=new Date().toISOString();let e=$('#ubi-estado');if(e)e.innerHTML=`<div class="tip">Ubicación lista ✓ (unos ${Math.round(u.acc||0)} m) · <a href="${mapPunto(u.lat,u.lng)}" target="_blank" rel="noopener">Ver en el mapa</a></div>`;let q=f.querySelector('.ubi-quitar');if(q)q.hidden=false}
function quitarUbicacionForm(){let f=$('#form');if(!f)return;f.elements.lat.value='';f.elements.lng.value='';f.elements.locAt.value='';let e=$('#ubi-estado');if(e)e.innerHTML='<p class="muted">Sin ubicación guardada.</p>';let q=f.querySelector('.ubi-quitar');if(q)q.hidden=true}
function ordenarRuta(inicio,paradas){let rest=paradas.slice(),out=[],cur=inicio;while(rest.length){let bi=0,bd=Infinity;rest.forEach((p,i)=>{let d=haversine(cur.lat,cur.lng,p.lat,p.lng);if(d<bd){bd=d;bi=i}});cur=rest.splice(bi,1)[0];out.push(cur)}let pts=[inicio,...out],mej=true,iter=0;while(mej&&iter<200){mej=false;iter++;for(let i=1;i<pts.length-1;i++){for(let j=i+1;j<pts.length-1;j++){let a=pts[i-1],b=pts[i],c=pts[j],d=pts[j+1],antes=haversine(a.lat,a.lng,b.lat,b.lng)+haversine(c.lat,c.lng,d.lat,d.lng),despues=haversine(a.lat,a.lng,c.lat,c.lng)+haversine(b.lat,b.lng,d.lat,d.lng);if(despues<antes-1e-9){pts.splice(i,j-i+1,...pts.slice(i,j+1).reverse());mej=true}}}}let res=[],prev=inicio;for(let i=1;i<pts.length;i++){let p=pts[i];p.dist=haversine(prev.lat,prev.lng,p.lat,p.lng);res.push(p);prev=p}return res}
function tramosMaps(inicio,paradas){let out=[],prev=inicio;for(let i=0;i<paradas.length;i+=10){let g=paradas.slice(i,i+10),dest=g[g.length-1],wps=g.slice(0,-1);out.push('https://www.google.com/maps/dir/?api=1&origin='+(prev.lat+','+prev.lng)+'&destination='+(dest.lat+','+dest.lng)+(wps.length?'&waypoints='+wps.map(p=>p.lat+','+p.lng).join('%7C'):'')+'&travelmode=driving');prev=dest}return out}
let ultimaRuta=null;
async function calcularRuta(){let orders=pedidosDeRuta(rutaFecha),paradas=new Map(),sinUbic=[];orders.forEach(o=>{let c=client(o.clientId);if(c&&tieneUbicacion(c)){let s=paradas.get(c.id)||{id:c.id,name:c.name,sector:c.sector,lat:Number(c.lat),lng:Number(c.lng),kg:0};s.kg+=Number(o.kg)||0;paradas.set(c.id,s)}else if(!sinUbic.some(x=>x.id===(c?c.id:o.clientId)))sinUbic.push(c||{id:o.clientId,name:o.clientName||'Cliente'})});let pts=[...paradas.values()];if(!pts.length){alert('Ningún cliente de esta ruta tiene ubicación guardada. Usa «📍 Guardar ubicación aquí» cuando estés en cada cliente.');return}let inicio=await obtenerUbicacion();if(!inicio){let ri=db.settings.rutaInicio;if(ri&&ri.lat!=null&&ri.lng!=null)inicio={lat:Number(ri.lat),lng:Number(ri.lng)}}if(!inicio)inicio={lat:pts[0].lat,lng:pts[0].lng};let orden=ordenarRuta(inicio,pts);ultimaRuta={start:inicio,paradas:orden,sinUbic};mostrarRutaCalculada()}
function mostrarRutaCalculada(){let r=ultimaRuta;if(!r)return;let tot=r.paradas.reduce((s,p)=>s+(p.dist||0),0),lista=r.paradas.map((p,i)=>`<div class="item"><div class="row"><div><h3>${i+1}. ${esc(p.name)}</h3><p>${kg(p.kg)} · ${esc(p.sector||'Sin sector')}</p></div><span class="badge">${km1(p.dist)} km</span></div></div>`).join(''),urls=tramosMaps(r.start,r.paradas),btns=urls.map((u,i)=>`<a class="button" href="${esc(u)}" target="_blank" rel="noopener" onclick="closeModal()">${urls.length===1?'Abrir en Google Maps':'Tramo '+(i+1)}</a>`).join('');openModal(`<div class="row"><h2>Ruta calculada</h2><button class="close" onclick="closeModal()">×</button></div><p class="muted">${r.paradas.length} parada${r.paradas.length===1?'':'s'} · ${km1(tot)} km aprox. en línea recta</p><div class="list">${lista}</div>${r.sinUbic.length?`<div class="spacer"></div><p class="muted"><b>Sin ubicación (visítalos aparte):</b> ${r.sinUbic.map(c=>esc(c.name||'Cliente')).join(', ')}</p>`:''}<div class="spacer"></div><div class="actions">${btns}<button class="secondary" onclick="usarOrdenRuta()">Usar este orden</button></div>`)}
function usarOrdenRuta(){if(!ultimaRuta)return;db.settings.rutaManual={fecha:rutaFecha,ids:ultimaRuta.paradas.map(p=>p.id)};save();closeModal();render();aviso('Orden de la ruta guardado')}
function idsRutaManual(){let m=db.settings.rutaManual;return m&&m.fecha===rutaFecha&&Array.isArray(m.ids)&&m.ids.length?m.ids:null}
function quitarRutaManual(){delete db.settings.rutaManual;save();render()}
let sugVerTodos=false;
function verSugeridosTodos(){sugVerTodos=true;render()}
function seccionSugeridos(){let sug=sugeridosParaRuta(rutaFecha);if(!sug.length)return '';let vis=sugVerTodos?sug:sug.slice(0,8),cards=vis.map(x=>{let c=x.c,motivo=x.f?'Compra cada '+x.f.cada+' días · '+(x.f.proxima===rutaFecha?'le toca hoy':'le toca desde el '+short(x.f.proxima)):'Lleva '+x.dias+' días sin comprar',phone=String(c.phone||'').trim();return `<article class="item"><div class="row"><div><h3>${esc(c.name)}</h3><p>${esc(c.sector||'Sin sector')}</p></div></div><p>${esc(motivo)}</p><p>Suele llevar ${kg(x.kg)}</p>${actions(`<button class="primary" onclick="agregarSugerido('${c.id}')">+ Pedido</button>${phone?`<button class="secondary" onclick="whatsapp('${c.id}')">WhatsApp ↗</button>`:''}<button class="secondary" onclick="hoyNo('${c.id}')">Hoy no</button>`)}</article>`}).join('');return head('Sugeridos para visitar','La app aprende cada cuánto compra cada cliente')+`<div class="list">${cards}</div>`+(sug.length>8&&!sugVerTodos?`<div class="spacer"></div><button class="secondary" onclick="verSugeridosTodos()">Ver todos (${sug.length})</button>`:'')}
function agregarSugerido(id){let c=client(id);if(!c)return;let sug=sugeridosParaRuta(rutaFecha).find(x=>x.c.id===id),k=sug&&sug.kg>0?sug.kg:1,ult=waUltima(id),price=Number(c.defaultPrice)||Number(ult?.price)||0;if(!price){editOrder(null,id);let f=$('#form');if(f){f.elements.kg.value=k;f.elements.date.value=rutaFecha}return}db.orders.push({id:uid(),clientId:id,kg:k,price,date:rutaFecha,notes:'',status:'Pendiente',paid:0});save();render();aviso('Pedido agregado a la ruta')}
function hoyNo(id){let c=client(id);if(!c)return;c.skipUntil=rutaFecha;save();render()}
async function guardarPuntoPartida(){let u=await obtenerUbicacion();if(!u)return;db.settings.rutaInicio={lat:u.lat,lng:u.lng};save();render();aviso('Punto de partida guardado')}
function contactadoHacePoco(c){let d=c.lastContact?diasDesde(c.lastContact):null;return d!==null&&d<7}
function clientesParaLlamar(){let lim=Number(db.settings.inactiveDays)||14;return db.clients.map(c=>({c,dias:diasSinComprar(c)})).filter(x=>x.dias!==null&&x.dias>=lim&&!db.orders.some(o=>o.clientId===x.c.id&&!delivered(o))&&!contactadoHacePoco(x.c)).sort((a,b)=>b.dias-a.dias).map(x=>x.c)}
function sectorDePedido(o){let c=client(o.clientId);return String(c?.sector??'').trim()||'Sin sector'}
function pedidosDeRuta(fecha){return db.orders.filter(o=>!delivered(o)&&(!o.date||o.date<=fecha))}
function gruposDeRuta(orders){let map=new Map();orders.forEach(o=>{let s=sectorDePedido(o);if(!map.has(s))map.set(s,[]);map.get(s).push(o)});return sectorOrder().filter(s=>map.has(s)).map(s=>({sector:s,pedidos:map.get(s).sort((a,b)=>byDate(a,b)||String(client(a.clientId)?.name||'').localeCompare(String(client(b.clientId)?.name||''),'es'))}))}
function rutaCard(o,num){let c=client(o.clientId),prev=o.clientId?owed(o.clientId):0,late=!!(o.date&&o.date<today()),phone=c?.phone?String(c.phone).trim():'';return `<article class="item"><div class="row"><div><h3>${num?num+'. ':''}${esc(c?.name||o.clientName||'Cliente no disponible')}</h3><p><b>${kg(o.kg)}</b> · ${money(total(o))}</p></div>${late?`<span class="badge neg">Atrasado desde ${short(o.date)}</span>`:''}</div>${prev>0?`<p class="neg">Debe además ${money(prev)}</p>`:''}${c?.address?`<p>${esc(c.address)}</p>`:''}${o.notes?`<p>${esc(o.notes)}</p>`:''}${actions(`<button class="primary" onclick="deliver('${o.id}')">✓ Entregar</button>${phone?`<a class="secondary" href="${esc(telLink(phone))}">Llamar</a>`:''}${c?.address||tieneUbicacion(c)?`<a class="secondary" href="${mapLink(c)}" target="_blank" rel="noopener">Mapa</a>`:''}`)}</article>`}
function mananaFecha(){let d=new Date();d.setDate(d.getDate()+1);return isoDate(d)}
function rutaPage(){let orders=pedidosDeRuta(rutaFecha),kilos=orders.reduce((s,o)=>s+(Number(o.kg)||0),0),st=stock(),falt=st!==null&&kilos>st?r3(kilos-st):0,cobrar=orders.reduce((s,o)=>s+total(o),0)+[...new Set(orders.map(o=>o.clientId).filter(Boolean))].reduce((s,id)=>s+owed(id),0),groups=gruposDeRuta(orders);let sel=`<div class="ruta-fecha"><button class="${rutaFecha===today()?'primary':'secondary'}" onclick="setRutaDia(today())">Hoy</button><button class="${rutaFecha===mananaFecha()?'primary':'secondary'}" onclick="setRutaDia(mananaFecha())">Mañana</button><input type="date" value="${esc(rutaFecha)}" aria-label="Elegir día de la ruta" onchange="setRutaDia(this.value)"></div>`,stats=`<div class="stats tres"><div class="stat"><small>Pedidos</small><strong>${orders.length}</strong><span>para la ruta</span></div><div class="stat"><small>Kilos a llevar</small><strong class="${falt>0?'neg':''}">${kg(kilos)}</strong><span class="${falt>0?'neg':''}">${falt>0?'Te faltan '+kg(falt):st===null?'Sin stock registrado':'Tienes '+kg(st)}</span></div><div class="stat"><small>Por cobrar en la ruta</small><strong>${money(cobrar)}</strong><span>incluye deudas anteriores</span></div></div>`;let ids=idsRutaManual(),sugHTML=seccionSugeridos(),toolbar=[];if(orders.some(o=>tieneUbicacion(client(o.clientId))))toolbar.push('<button class="primary" onclick="calcularRuta()">🧭 Calcular ruta más corta</button>');if(ids)toolbar.push('<button class="secondary" onclick="quitarRutaManual()">Volver a ordenar por sector</button>');let grupoHTML=(g,i,n)=>{let gk=g.pedidos.reduce((s,o)=>s+(Number(o.kg)||0),0),mov=`<div class="sector-move"><button class="secondary" ${i===0||g.sector==='Sin sector'?'disabled':''} onclick="moveSector(${jsq(g.sector)},-1)" title="Subir sector">↑</button><button class="secondary" ${i===n-1||g.sector==='Sin sector'?'disabled':''} onclick="moveSector(${jsq(g.sector)},1)" title="Bajar sector">↓</button></div>`;return `<div class="sector-head"><h3>${esc(g.sector)} · ${g.pedidos.length} pedido${g.pedidos.length===1?'':'s'} · ${kg(gk)}</h3>${mov}</div><div class="list">${g.pedidos.map(o=>rutaCard(o)).join('')}</div>`};if(!orders.length)return sel+stats+empty('Sin entregas para este día','Cambia el día o agrega un pedido.')+sugHTML;let body='';if(ids){let flat=[],usados=new Set();ids.forEach(id=>orders.filter(o=>o.clientId===id).forEach(o=>{if(!usados.has(o.id)){usados.add(o.id);flat.push(o)}}));let resto=orders.filter(o=>!usados.has(o.id));body=(flat.length?`<div class="list">${flat.map((o,i)=>rutaCard(o,i+1)).join('')}</div>`:'')+(resto.length?gruposDeRuta(resto).map((g,i,a)=>grupoHTML(g,i,a.length)).join(''):'')}else body=groups.map((g,i,a)=>grupoHTML(g,i,a.length)).join('');return sel+stats+(toolbar.length?actions(toolbar.join('')):'')+body+`<div class="spacer"></div>${actions('<button class="primary" onclick="compartirRuta()">Compartir ruta</button>')}`+sugHTML}
function setPedidosVista(v){pedidosVista=v==='todos'?'todos':'ruta';render()}
function setRutaDia(fecha){rutaFecha=fecha||today();render()}
function verRutaHoy(){page='pedidos';pedidosVista='ruta';rutaFecha=today();render()}
function marcarContactado(id){let c=client(id);if(!c)return;c.lastContact=today();save();render()}
function saveSettings(){let v=Number($('#inactive-days')?.value);if(!Number.isFinite(v))v=14;v=Math.max(3,Math.min(90,Math.round(v)));db.settings.inactiveDays=v;save();render()}
function rutaTexto(){let orders=pedidosDeRuta(rutaFecha),ids=idsRutaManual(),lines=['Ruta del '+fmt(rutaFecha)];if(ids){let flat=[],usados=new Set();ids.forEach(id=>orders.filter(o=>o.clientId===id).forEach(o=>{if(!usados.has(o.id)){usados.add(o.id);flat.push(o)}}));orders.filter(o=>!usados.has(o.id)).forEach(o=>flat.push(o));flat.forEach((o,i)=>{let c=client(o.clientId),parts=[c?.name||o.clientName||'Cliente',kg(o.kg)];if(c?.address)parts.push(c.address);parts.push(money(total(o)));lines.push((i+1)+'. '+parts.join(' · '))});return lines.join('\n')}let groups=gruposDeRuta(orders);groups.forEach(g=>{lines.push('');lines.push(g.sector+' · '+g.pedidos.length+' pedido'+(g.pedidos.length===1?'':'s')+' · '+kg(g.pedidos.reduce((s,o)=>s+(Number(o.kg)||0),0)));g.pedidos.forEach(o=>{let c=client(o.clientId),parts=[c?.name||o.clientName||'Cliente',kg(o.kg)];if(c?.address)parts.push(c.address);parts.push(money(total(o)));lines.push('• '+parts.join(' · '))})});return lines.join('\n')}
async function compartirRuta(){let text=rutaTexto();if(navigator.share){try{await navigator.share({text});return}catch(e){if(e&&e.name==='AbortError')return}}if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);alert('Ruta copiada');return}catch{}}openModal(`<div class="row"><h2>Compartir ruta</h2><button class="close" onclick="closeModal()">×</button></div><p class="muted">Copia el texto y envíalo por WhatsApp o mensaje.</p><textarea readonly>${esc(text)}</textarea><div class="form-actions"><button class="secondary" onclick="closeModal()">Cerrar</button></div>`)}

function migrateV22(){if(db.v22)return;if(db.stockBase!==null){let old=Number(db.stockBase)||0,at=db.stockAt||'';if(at){db.purchases.forEach(x=>{if((x.createdAt||'')>=at)old+=Number(x.kg)||0});db.losses.forEach(x=>{if((x.createdAt||'')>=at)old-=Number(x.kg)||0});db.orders.forEach(x=>{if(delivered(x)&&(x.deliveredAt||'')>=at)old-=Number(x.kg)||0})}let diff=r3(old-ledger().stock);if(diff>0.001)db.purchases.push({id:uid(),date:db.stockDate||today(),name:'Stock inicial (conteo)',kg:diff,price:0,extra:0,notes:'Creada al pasar a la versión 2.2. Puedes editar su precio.',createdAt:db.stockAt});else if(diff<-0.001)db.losses.push({id:uid(),date:db.stockDate||today(),kg:-diff,cause:'Ajuste de conteo',notes:'',createdAt:db.stockAt})}db.stockBase=null;db.v22=true;save()}

function tandaCard(b){let active=b.left>0,gain=b.sales-b.soldCost-b.lossCost;return `<article class="item"><div class="row"><div><h3>Tanda del ${fmt(b.date)} · ${esc(b.name||'Sin proveedor')}</h3></div><span class="badge">${active?'En venta · quedan '+kg(b.left):'Terminada'}</span></div><p>Comprados ${kg(b.kg)} a ${money(b.p.price)}/kg + gastos ${money(b.p.extra)} = ${money(b.cost)} (${money(b.costKg)} por kilo)</p><p>Vendidos ${kg(b.soldKg)} por ${money(b.sales)} · Perdidos ${kg(b.lossKg)}</p><p>Ganancia: <b class="${gain>=0?'pos':'neg'}">${money(gain)}</b>${active?' (hasta ahora)':''}</p>${!(Number(b.p.price)>0)&&b.kg>0?`<p class="neg">Esta tanda no tiene precio de compra, así que su ganancia sale más alta de lo real. Toca «Editar» y pon lo que te costó el kilo.</p>`:''}${b.p.notes?`<p>${esc(b.p.notes)}</p>`:''}${actions(`${active?`<button class="secondary" onclick="closeBatch('${b.id}')">Cerrar tanda</button>`:''}<button class="secondary" onclick="editPurchase('${b.id}')">Editar</button><button class="secondary danger" onclick="deleteMove('Compra','${b.id}')">Eliminar</button>`)}</article>`}

function lossRow(l,lg){let a=lg.lossAlloc[l.id]||[],bid=(l.batchId&&lg.batches.some(x=>x.id===l.batchId))?l.batchId:a[0]?.batchId,b=lg.batches.find(x=>x.id===bid),where=b?'Tanda del '+fmt(b.date)+(b.name?' · '+esc(b.name):''):'Sin tanda asignada';return `<article class="item"><div class="row"><div><h3>${kg(l.kg)} · ${esc(l.cause||'Merma')}</h3><p>${fmt(l.date)} · ${where}</p></div><span class="badge neg">${money(lg.lossCost[l.id]||0)}</span></div>${l.notes?`<p>${esc(l.notes)}</p>`:''}${actions(`<button class="secondary danger" onclick="deleteMove('Merma','${l.id}')">Eliminar</button>`)}</article>`}

function closeBatch(id){let b=ledger().batches.find(x=>x.id===id);if(!b||b.left<=0)return;let k=Number(b.left);if(!confirm('Quedan '+kg(k)+' en esta tanda. Se anotarán como merma por cierre de tanda. ¿Continuar?'))return;db.losses.push({id:uid(),batchId:id,kg:k,cause:'Cierre de tanda',date:today(),createdAt:new Date().toISOString(),notes:''});save();render()}

function tandasPage(){let lg=ledger(),s=lg.stock,active=lg.batches.filter(b=>b.left>0).sort((a,b)=>(a.date||'').localeCompare(b.date||'')||(a.p.createdAt||'').localeCompare(b.p.createdAt||'')),done=lg.batches.filter(b=>b.left<=0).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.p.createdAt||'').localeCompare(a.p.createdAt||'')),losses=[...db.losses].sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.createdAt||'').localeCompare(a.createdAt||''));return head('Tandas','Tus compras, los kilos que quedan y la ganancia de cada tanda')+`<div class="card"><div class="row"><div><h3>Kilos disponibles: <span class="${s<0?'neg':''}">${kg(s)}</span></h3><p class="muted">${s<0?'Hay entregas o mermas sin compra registrada.':'Calculado a partir de tus tandas.'}</p></div></div>${actions('<button class="secondary" onclick="purchase()">+ Compra</button><button class="secondary" onclick="loss()">+ Merma</button><button class="secondary" onclick="setStock()">Nuevo conteo</button>')}</div>`+head('Tandas en venta',active.length?'Primero las más antiguas':'No quedan kilos disponibles')+`<div class="list">${active.length?active.map(tandaCard).join(''):empty('No hay tandas con kilos','Registra una compra para comenzar una tanda.')}</div>`+(done.length?head('Tandas terminadas','Las más recientes primero')+`<div class="list">${done.map(tandaCard).join('')}</div>`:'')+head('Mermas','Pérdidas registradas y de qué tanda salieron')+`<div class="list">${losses.length?losses.map(l=>lossRow(l,lg)).join(''):empty('Sin mermas','Cuando pierdas kilos, regístralos aquí.')}</div>`}

function isoDate(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function mondayOf(s){let [y,m,d]=s.split('-').map(Number),x=new Date(y,m-1,d);x.setDate(x.getDate()-((x.getDay()+6)%7));return isoDate(x)}
function rangoPeriodo(p){let t=today(),y=Number(t.slice(0,4)),m=Number(t.slice(5,7)),mm=String(m).padStart(2,'0');if(p==='Esta semana')return[mondayOf(t),t];if(p==='Este mes')return[y+'-'+mm+'-01',t];if(p==='Mes pasado'){let y2=m===1?y-1:y,m2=m===1?12:m-1,m2s=String(m2).padStart(2,'0'),last=new Date(y2,m2,0).getDate();return[y2+'-'+m2s+'-01',y2+'-'+m2s+'-'+String(last).padStart(2,'0')]}return['0000-01-01','9999-12-31']}

function reporte(desde,hasta){let lg=ledger(),orders=db.orders.filter(o=>{if(!delivered(o))return false;let d=o.deliveredDate||o.date||'';return d>=desde&&d<=hasta}),losses=db.losses.filter(l=>{let d=l.date||'';return d>=desde&&d<=hasta}),pays=db.payments.filter(p=>{let d=p.date||'';return d>=desde&&d<=hasta}),ventas=0,kgV=0,costo=0;orders.forEach(o=>{ventas+=total(o);kgV+=Number(o.kg)||0;costo+=lg.orderCost[o.id]||0});let mermaKg=0,costoMerma=0;losses.forEach(l=>{mermaKg+=Number(l.kg)||0;costoMerma+=lg.lossCost[l.id]||0});let ganancia=ventas-costo-costoMerma,cobrado=pays.reduce((s,p)=>s+(Number(p.amount)||0),0);return{lg,orders,losses,pays,ventas,kgV,costo,mermaKg,costoMerma,ganancia,cobrado,porcentajeMerma:(kgV+mermaKg)>0?mermaKg/(kgV+mermaKg):0,margen:ventas?ganancia/ventas:0,porKilo:kgV?ganancia/kgV:0}}

function semanas(rep){let map=new Map(),get=w=>{if(!map.has(w))map.set(w,{w,kg:0,ventas:0,mermas:0,ganancia:0});return map.get(w)};rep.orders.forEach(o=>{let d=o.deliveredDate||o.date||'';if(!d)return;let g=get(mondayOf(d));g.kg+=Number(o.kg)||0;g.ventas+=total(o);g.ganancia+=total(o)-(rep.lg.orderCost[o.id]||0)});rep.losses.forEach(l=>{let d=l.date||'';if(!d)return;let g=get(mondayOf(d)),c=rep.lg.lossCost[l.id]||0;g.mermas+=c;g.ganancia-=c});return[...map.values()].sort((a,b)=>b.w.localeCompare(a.w))}

function topClientes(rep){let map=new Map();rep.orders.forEach(o=>{let key=o.clientId||('n:'+(o.clientName||'Sin cliente')),g=map.get(key)||{name:client(o.clientId)?.name||o.clientName||'Cliente no disponible',kg:0,ganancia:0};g.kg+=Number(o.kg)||0;g.ganancia+=total(o)-(rep.lg.orderCost[o.id]||0);map.set(key,g)});return[...map.values()].sort((a,b)=>b.ganancia-a.ganancia).slice(0,5)}

function setPeriodo(p){periodo=p;render()}

function gananciasPage(){let [desde,hasta]=rangoPeriodo(periodo),rep=reporte(desde,hasta),sel='<div class="actions">'+['Esta semana','Este mes','Mes pasado','Todo'].map(p=>`<button class="${periodo===p?'primary':'secondary'}" onclick="setPeriodo('${p}')">${p}</button>`).join('')+'</div>',html=head('Ganancias','Lo que ganas de verdad, después de costos y mermas')+sel;if(!rep.orders.length)return html+empty('Sin entregas en este periodo','Cambia el periodo o registra una entrega para ver tus números.')+`<div class="tip"><b>Cómo se calcula</b><br>Ganancia = lo que vendiste − lo que te costaron esas paltas (con los gastos del viaje) − el costo de las paltas perdidas.</div>`;html+=`<div class="stats"><div class="stat"><small>Ganancia</small><strong class="${rep.ganancia>=0?'pos':'neg'}">${money(rep.ganancia)}</strong><span>${periodo.toLowerCase()}</span></div><div class="stat"><small>Ventas</small><strong>${money(rep.ventas)}</strong><span>${rep.orders.length} entrega${rep.orders.length===1?'':'s'}</span></div><div class="stat"><small>Kilos vendidos</small><strong>${kg(rep.kgV)}</strong><span>en el periodo</span></div><div class="stat"><small>Mermas</small><strong>${kg(rep.mermaKg)}</strong><span>${money(rep.costoMerma)} · ${pct(rep.porcentajeMerma)}</span></div></div><div class="spacer"></div><div class="card"><h3>Detalle del periodo</h3><div class="line"><span class="muted">Costo de lo vendido</span><b>${money(rep.costo)}</b></div><div class="line"><span class="muted">Costo de las mermas</span><b>${money(rep.costoMerma)}</b></div><div class="line"><span class="muted">Margen</span><b class="${rep.margen>=0?'pos':'neg'}">${pct(rep.margen)}</b></div><div class="line"><span class="muted">Ganancia por kilo vendido</span><b>${money(rep.porKilo)}</b></div><div class="line"><span class="muted">Cobrado en el periodo</span><b>${money(rep.cobrado)}</b></div><div class="line"><span class="muted">Por cobrar (total)</span><b>${money(owed())}</b></div></div>`;let sem=semanas(rep),top=topClientes(rep);if(sem.length)html+=head('Por semana','Semanas que empiezan en lunes, de la más reciente a la más antigua')+`<div class="list">${sem.map(w=>`<article class="item"><div class="row"><div><h3>Semana del ${short(w.w)}</h3><p>${kg(w.kg)} vendidos · ${money(w.ventas)} en ventas${w.mermas>0.001?' · mermas '+money(w.mermas):''}</p></div><b class="${w.ganancia>=0?'pos':'neg'}">${money(w.ganancia)}</b></div></article>`).join('')}</div>`;if(top.length)html+=head('Mejores clientes del periodo','Los 5 con más ganancia')+`<div class="list">${top.map(t=>`<article class="item"><div class="row"><div><h3>${esc(t.name)}</h3><p>${kg(t.kg)} comprados</p></div><b class="${t.ganancia>=0?'pos':'neg'}">${money(t.ganancia)}</b></div></article>`).join('')}</div>`;if(rep.lg.batches.some(b=>!(Number(b.p.price)>0)&&b.soldKg>0.001))html+=`<div class="tip"><b>Hay tandas sin precio</b><br>Algunas paltas vendidas salen de tandas sin precio de compra (por ejemplo «Stock inicial»). Ponles precio en Tandas → Editar para que la ganancia sea real.</div>`;if(rep.lg.unassignedKg>0.001)html+=`<div class="tip"><b>Revisa tus compras</b><br>Hay ${kg(rep.lg.unassignedKg)} entregados sin compra registrada; la ganancia puede salir más alta de lo real. Registra tus compras en Tandas.</div>`;html+=`<div class="tip"><b>Cómo se calcula</b><br>Ganancia = lo que vendiste − lo que te costaron esas paltas (con los gastos del viaje) − el costo de las paltas perdidas.</div>`;return html}
function ppClientes(x){let d=x&&typeof x==='object'?(x.data&&typeof x.data==='object'?x.data:x):null;return d&&Array.isArray(d.clientes)?d.clientes:null}
function normName(t){return String(t||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/\s+/g,' ').trim()}
function normPhone(t){return String(t||'').replace(/\D/g,'').slice(-8)}
function guessSector(t){let n=normName(t);return SECTORES.find(x=>n.includes(normName(x)))||''}
function importPaltasPro(input){let f=input.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let list=ppClientes(JSON.parse(r.result));if(!list)throw Error();showPPImport(list)}catch{alert('Este archivo no es una copia de PaltasPro. Suele llamarse «paltaspro-backup-…json».')}finally{input.value=''}};r.readAsText(f)}
function ppPreparar(list){let names=new Set(db.clients.map(c=>normName(c.name))),phones=new Set(db.clients.map(c=>normPhone(c.phone)).filter(p=>p.length===8)),nuevos=[],repetidos=0;list.forEach(c=>{let name=String(c?.nombre||'').trim();if(!name)return;let n=normName(name),ph=normPhone(c?.telefono);if(names.has(n)||(ph.length===8&&phones.has(ph))){repetidos++;return}names.add(n);if(ph.length===8)phones.add(ph);let nt=String(c?.notas||'').trim();if(nt&&!/[.!?]$/.test(nt))nt+='.';let notes=[nt,c?.pago==='credito'?'En PaltasPro pagaba a crédito.':''].filter(Boolean).join(' ');nuevos.push({id:uid(),name,phone:String(c?.telefono||'').trim(),sector:guessSector(c?.direccion),address:String(c?.direccion||'').trim(),defaultPrice:Number(c?.precio)>0?String(Math.round(Number(c.precio))):'',notes})});return{nuevos,repetidos}}
function showPPImport(list){let {nuevos,repetidos}=ppPreparar(list),cab=`<div class="row"><h2>Clientes de PaltasPro</h2><button class="close" onclick="closeModal()">×</button></div>`,res=`<p class="muted">En la copia hay ${nuevos.length+repetidos} cliente${nuevos.length+repetidos===1?'':'s'}. ${nuevos.length} ${nuevos.length===1?'es nuevo':'son nuevos'}${repetidos?` y ${repetidos} se ${repetidos===1?'salta':'saltan'} porque ya ${repetidos===1?'está':'están'} en Kpal o ${repetidos===1?'se repite':'se repiten'} en la copia`:''}.</p>`;if(!nuevos.length){openModal(cab+res+`<div class="form-actions"><button class="primary" onclick="closeModal()">Entendido</button></div>`);return}openModal(cab+res+`<form id="form"><div class="actions"><button type="button" class="secondary" onclick="document.querySelectorAll('#form input[type=checkbox]').forEach(x=>x.checked=true)">Marcar todos</button><button type="button" class="secondary" onclick="document.querySelectorAll('#form input[type=checkbox]').forEach(x=>x.checked=false)">Quitar todos</button></div><div style="max-height:50vh;overflow:auto;margin:12px 0">${nuevos.map((c,i)=>`<label style="display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid #eef1e8"><input type="checkbox" name="i" value="${i}" checked style="width:auto;margin-top:3px"><span><b>${esc(c.name)}</b><br><span class="muted">${esc(c.phone||'Sin teléfono')} · ${esc(c.sector||'Sin sector')}${c.defaultPrice?' · '+money(c.defaultPrice)+'/kg':''}</span></span></label>`).join('')}</div><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Agregar clientes</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let sel=new FormData(e.target).getAll('i').map(Number),add=sel.map(i=>nuevos[i]).filter(Boolean);if(!add.length){alert('No marcaste ningún cliente.');return}db.clients.push(...add);save();closeModal();go('clientes');alert('Listo: '+(add.length===1?'se agregó 1 cliente':'se agregaron '+add.length+' clientes')+'. Revisa su sector en «Editar» si falta.')}}

/* v2.5: pantalla Nueva venta */
var ventaDraft=null;
function ventaPage(){let st=stock(),hoy=db.orders.filter(o=>delivered(o)&&(o.deliveredDate||o.date)===today()).sort((a,b)=>(b.deliveredAt||'').localeCompare(a.deliveredAt||'')),totHoy=hoy.reduce((s,o)=>s+total(o),0),kgHoy=hoy.reduce((s,o)=>s+(Number(o.kg)||0),0);
return head('Nueva venta',st===null?'Anota lo que vendes ahora mismo':'Te quedan '+kg(st)+' según tus registros')+`<div class="card venta"><form id="venta-form"><label>Cliente<div class="venta-cliente"><select name="clientId" id="v-client" required><option value="">${db.clients.length?'Elige un cliente':'Primero agrega un cliente →'}</option>${[...db.clients].sort((a,b)=>String(a.name).localeCompare(String(b.name),'es')).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}${c.sector?' · '+esc(c.sector):''}</option>`).join('')}</select><button type="button" class="secondary" onclick="ventaNuevoCliente()">+ Nuevo</button></div></label><p class="muted" id="v-deuda" hidden></p><div class="grid dos"><label>Kilos<input name="kg" id="v-kg" type="number" min="0.01" step="0.01" inputmode="decimal" required></label><label>Precio por kilo ($)<input name="price" id="v-price" type="number" min="1" step="1" inputmode="numeric" required></label></div><div class="venta-total"><span>Total de la venta</span><strong id="v-total">$0</strong></div><p class="neg" id="v-falta" hidden></p><label>¿Cuánto te pagó ahora? ($)<input name="amount" id="v-amount" type="number" min="0" step="1" inputmode="numeric" value="0" required></label><div class="actions venta-pago"><button type="button" class="secondary" onclick="ventaPago('todo')">Pagó todo</button><button type="button" class="secondary" onclick="ventaPago('nada')">Paga después</button></div><p class="muted" id="v-pago-nota"></p><details><summary>Fecha y notas</summary><label>Fecha<input name="date" id="v-date" type="date" required value="${today()}"></label><label>Notas<textarea name="notes" id="v-notes"></textarea></label></details><button class="primary venta-ok">✓ Registrar venta</button><button type="button" class="secondary" onclick="ventaComoPedido()">Guardar como pedido para entregar después</button></form></div><div class="section-head row"><div><h2>Ventas de hoy</h2><p>${hoy.length?hoy.length+' venta'+(hoy.length===1?'':'s')+' · '+kg(kgHoy)+' · '+money(totHoy):'Aún no hay ventas hoy'}</p></div></div><div class="list">${hoy.length?hoy.map(o=>`<article class="item row"><div><h3>${esc(client(o.clientId)?.name||'Cliente')}</h3><p>${kg(o.kg)} × ${money(o.price)} · ${balance(o)>0?'<span class="neg">debe '+money(balance(o))+'</span>':'pagado'}</p></div><b>${money(total(o))}</b></article>`).join(''):empty('Sin ventas todavía','Las ventas que registres hoy aparecerán aquí.')}</div>`}
function ventaDatos(){let f=$('#venta-form');return f?Object.fromEntries(new FormData(f)):null}
function ventaTotal(){return Math.round((Number($('#v-kg').value)||0)*(Number($('#v-price').value)||0))}
function ventaCalc(){let c=$('#v-client').value,k=Number($('#v-kg').value)||0,t=ventaTotal(),prev=c?owed(c):0,max=prev+t,a=$('#v-amount');$('#v-total').textContent=money(t);a.max=max;let dn=$('#v-deuda');dn.hidden=!(prev>0);dn.innerHTML=prev>0?'Ya debía <b class="neg">'+money(prev)+'</b>. Lo que pague se aplica primero a lo más antiguo.':'';let st=stock(),fl=$('#v-falta');fl.hidden=!(st!==null&&k>st+1e-9);fl.textContent=fl.hidden?'':'Ojo: según tus registros solo te quedan '+kg(st)+'.';let am=Number(a.value)||0,n=$('#v-pago-nota');n.textContent=t?(am>=max?'Queda todo pagado.':'Quedará debiendo '+money(max-am)+'.'):''}
function ventaPago(x){$('#v-amount').value=x==='todo'?ventaTotal():0;ventaCalc()}
function ventaInit(){let f=$('#venta-form');if(!f)return;if(ventaDraft){let d=ventaDraft;['kg','price','amount','date','notes'].forEach(k=>{if(d[k]!=null&&d[k]!=='')f.elements[k].value=d[k]});if(db.clients.length>d.count){let n=db.clients[db.clients.length-1];$('#v-client').value=n.id;if(!d.price&&n.defaultPrice)$('#v-price').value=n.defaultPrice}else $('#v-client').value=d.clientId||'';ventaDraft=null}
$('#v-client').onchange=e=>{let c=client(e.target.value);if(c?.defaultPrice)$('#v-price').value=c.defaultPrice;ventaCalc()};['#v-kg','#v-price','#v-amount'].forEach(s=>$(s).oninput=ventaCalc);ventaCalc();
f.onsubmit=e=>{e.preventDefault();let d=ventaDatos(),k=Number(d.kg),t=Math.round(k*Number(d.price)),max=owed(d.clientId)+t,am=Math.min(Math.max(0,Math.round(Number(d.amount)||0)),max),st=stock();if(st!==null&&k>st+1e-9&&!confirm('Según tus registros solo te quedan '+kg(st)+' y esta venta es de '+kg(k)+'. ¿Registrar igual?'))return;db.orders.push({id:uid(),clientId:d.clientId,kg:d.kg,price:d.price,date:d.date,notes:d.notes||'',status:'Entregado',paid:0,deliveredAt:new Date().toISOString(),deliveredDate:d.date});if(am>0)allocate(d.clientId,am,d.date);save();render();aviso('Venta registrada: '+kg(k)+' a '+(client(d.clientId)?.name||'cliente')+' por '+money(t))}}
function ventaNuevoCliente(){ventaDraft={...ventaDatos(),count:db.clients.length};editClient()}
function ventaComoPedido(){let f=$('#venta-form');if(!f.reportValidity())return;let d=ventaDatos();db.orders.push({id:uid(),clientId:d.clientId,kg:d.kg,price:d.price,date:d.date,notes:d.notes||'',status:'Pendiente',paid:0});save();render();aviso('Pedido guardado para el '+fmt(d.date)+'. Lo verás en Pedidos.')}
function aviso(t){let a=document.createElement('div');a.className='aviso';a.textContent=t;document.body.appendChild(a);setTimeout(()=>a.classList.add('fuera'),2600);setTimeout(()=>a.remove(),3100)}
function km1(n){return (Number(n)||0).toLocaleString('es-CL',{minimumFractionDigits:1,maximumFractionDigits:1})}

/* v2.8: app instalable y sin internet */
var pedirInstalar=null;
function esInstalada(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function tarjetaInstalar(){if(esInstalada())return '';let seguro=location.protocol==='https:'||location.hostname==='localhost';return `<div class="card"><h3>📲 Instalar Kpal en el móvil</h3><p class="muted">${!seguro?'Para instalarla, abre Kpal desde su enlace de internet (https).':pedirInstalar?'Tendrás el icono de Kpal en tu pantalla y funcionará sin internet.':'En Chrome, toca los tres puntos ⋮ de arriba y elige «Instalar app» o «Añadir a pantalla de inicio».'}</p>${pedirInstalar?'<button class="primary" onclick="instalarApp()">Instalar Kpal</button>':''}</div><div class="spacer"></div>`}
async function instalarApp(){if(!pedirInstalar)return;pedirInstalar.prompt();try{await pedirInstalar.userChoice}catch{}pedirInstalar=null;render()}
addEventListener('beforeinstallprompt',e=>{e.preventDefault();pedirInstalar=e;if(page==='mas')render()});
addEventListener('appinstalled',()=>{pedirInstalar=null;aviso('Kpal quedó instalada en tu móvil');if(page==='mas')render()});
if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('sw.js').catch(()=>{})
if(navigator.storage&&navigator.storage.persist)navigator.storage.persist().catch(()=>{});
function guardarNombre(){db.settings.nombre=String($('#mi-nombre')?.value||'').trim();save();render();aviso('Nombre guardado')}

/* v2.9: elegir con qué WhatsApp se envía */
const WA_APPS=[['','Chat directo (más rápido)'],['compartir','Menú de compartir']];
function opcionesWaApp(v){v=v==='compartir'?'compartir':'';return WA_APPS.map(([k,t])=>`<option value="${k}" ${k===v?'selected':''}>${t}</option>`).join('')}
function guardarWaApp(){db.settings.waApp=$('#wa-app-def')?.value==='compartir'?'compartir':'';save();render();aviso('WhatsApp para vender guardado')}
function abrirWhatsApp(phone,msg,app){let web='https://wa.me/'+phone+'?text='+encodeURIComponent(msg),pkg=app==='business'?'com.whatsapp.w4b':app==='personal'?'com.whatsapp':'';if(/Android/i.test(navigator.userAgent)){location.href='intent://send/?phone='+phone+'&text='+encodeURIComponent(msg)+'#Intent;scheme=whatsapp;'+(pkg?'package='+pkg+';':'')+'S.browser_fallback_url='+encodeURIComponent(web)+';end';return}window.open(web,'_blank','noopener')}
if(!db.settings.waV211){db.settings.waApp='';db.settings.waV210=true;db.settings.waV211=true;save()}
